import sys

def find_path_length(n, a, b):
    if n == 0:
        return 0
    elif n == 1:
        return 1

    sizes = [0] * (n + 1)
    sizes[0] = 1
    sizes[1] = 2

    for i in range(2, n + 1):
        sizes[i] = sizes[i - 1] + sizes[i - 2]

    def find_in_graph(n, v):
        if n == 0:
            return 1, 0
        elif n == 1:
            return v, 1

        size_n1 = sizes[n - 1]
        if v <= size_n1:
            return find_in_graph(n - 1, v)
        else:
            v_new = v - size_n1
            return find_in_graph(n - 2, v_new), size_n1

    pos_a, offset_a = find_in_graph(n, a)
    pos_b, offset_b = find_in_graph(n, b)

    if pos_a == pos_b:
        return abs(offset_a - offset_b)

    return abs(offset_a - 1) + abs(offset_b - 1) + 1

def main():
    import sys
    input = sys.stdin.read().split()
    t = int(input[0])
    n = int(input[1])
    queries = [(int(input[2 + 2 * i]), int(input[3 + 2 * i])) for i in range(t)]
    results = []
    for a, b in queries:
        results.append(find_path_length(n, a, b))
    print('\n'.join(map(str, results)))

main()
